fn retained_partition_pages(document: &Document) -> Option<Vec<ObjectId>> {
    let catalog = catalog_dict(document).ok()?;
    if name_at(catalog, "Type").as_deref() != Some("Catalog") { return None; }
    let tree = catalog.get(b"Pages").ok()?.as_reference().ok()?;
    if name_at(document.get_dictionary(tree).ok()?, "Type").as_deref() != Some("Pages") { return None; }
    let mut pending = vec![(tree, None, false)];
    let mut seen = std::collections::HashSet::new();
    let mut counts = std::collections::HashMap::<ObjectId, usize>::new();
    let mut pages = Vec::new();
    while let Some((id, parent, finishing)) = pending.pop() {
        let node = document.get_dictionary(id).ok()?;
        if finishing {
            let mut count = 0usize;
            for child in node.get(b"Kids").ok()?.as_array().ok()? { count = count.checked_add(*counts.get(&child.as_reference().ok()?)?)?; }
            let Object::Integer(declared) = node.get(b"Count").ok()? else { return None; };
            if *declared != i64::try_from(count).ok()? { return None; }
            counts.insert(id, count);
            continue;
        }
        if !seen.insert(id) { return None; }
        if let Some(parent) = parent { if node.get(b"Parent").ok()?.as_reference().ok()? != parent { return None; } }
        match name_at(node, "Type").as_deref() {
            Some("Page") => { pages.push(id); counts.insert(id, 1); }
            Some("Pages") => { pending.push((id, parent, true)); for child in node.get(b"Kids").ok()?.as_array().ok()?.iter().rev() { pending.push((child.as_reference().ok()?, Some(id), false)); } }
            _ => return None,
        }
    }
    (!pages.is_empty()).then_some(pages)
}

/// 🗂️ Reads every retained partition node through actual Parent, Start and DPM.Job roles.
fn dpart_nodes(document: &Document) -> Option<(ObjectId, Vec<(ObjectId, Option<String>)>)> {
    let pages = retained_partition_pages(document)?;
    let catalog = catalog_dict(document).ok()?;
    let root_id = catalog.get(b"DPartRoot").ok()?.as_reference().ok()?;
    let root = document.get_dictionary(root_id).ok()?;
    if name_at(root, "Type").as_deref() != Some("DPartRoot") { return None; }
    let node_id = root.get(b"DPartRootNode").ok()?.as_reference().ok()?;
    let mut pending = vec![(node_id, root_id)];
    let mut seen = std::collections::HashSet::new();
    let mut nodes = Vec::new();
    while let Some((id, parent)) = pending.pop() {
        if !seen.insert(id) { return None; }
        let node = document.get_dictionary(id).ok()?;
        if name_at(node, "Type").as_deref() != Some("DPart") || node.get(b"Parent").ok()?.as_reference().ok()? != parent { return None; }
        let children = match node.get(b"DParts") { Ok(value) => Some(value.as_array().ok()?), Err(_) => None };
        if children.map_or(true, |children| children.is_empty()) || node.get(b"Start").is_ok() { if !pages.contains(&node.get(b"Start").ok()?.as_reference().ok()?) { return None; } }
        let metadata = node.get(b"DPM").ok().and_then(|value| deref_dict(document, value)).and_then(|dict| text_at(dict, "Job"));
        nodes.push((id, metadata));
        if let Some(children) = children { for child in children.iter().rev() { pending.push((child.as_reference().ok()?, id)); } }
    }
    Some((root_id, nodes))
}

